(function () {
  const ENGLISH_STORIES = {
    "picture-story.html": {
      title: "The Little Scientist of Starlight Lab",
      lead: "A story about Minjun, a boy who builds rockets and robots while growing his dream.",
      pages: [
        ["Starlight Lab", "Minjun loved stars very much. At night, he sat by the window and watched the sparkling stars.", "\"Someday I will ride a rocket I made and go close to the stars.\""],
        ["The First Blueprint", "On Minjun's desk were colored pencils, paper, and tiny parts. He drew a rocket on a big sheet of paper.", "\"Strong wings and round windows!\""],
        ["A Safe Scientist", "Minjun put on a white coat and safety glasses. He carefully took out a small screwdriver, paper cups, and straws.", "\"A scientist makes things safely.\""],
        ["Rocket Complete!", "The rocket body shone, and blue wings stood proudly on both sides. Minjun put a yellow star sticker on the tip.", "\"Its name is Star Bean Rocket!\""],
        ["Toto the Robot Friend", "This time he made a robot with round eyes. The robot's name was Toto. Toto blinked its blue eyes.", "\"Beep beep! Dr. Minjun, how may I help you?\""],
        ["The First Test Fails", "Minjun and Toto tried to launch the rocket. But it did not fly into the sky. It rolled sideways instead.", "\"It's okay. Failure is a signal to think again.\""],
        ["Fixing It Again", "Toto checked the balance of the rocket wings. Minjun moved the wings a little and looked inside the body again.", "\"If we fix it little by little, it becomes a better invention.\""],
        ["The Rocket Soars High", "On the second test, Star Bean Rocket rose straight, slowly, and high. The stars outside seemed to clap and sparkle.", "\"It worked!\""],
        ["A Bigger Dream", "That night, Minjun drew a new blueprint. It showed a bigger rocket, smarter robots, and a space ship for friends.", "\"Next time, let's all travel to the stars together.\""],
        ["The Little Scientist's Heart", "Minjun learned something. A scientist is not someone who does everything perfectly at once, but someone who wonders, tries again, and keeps imagining.", "The light of Starlight Lab glowed warmly for a long time that night."]
      ]
    },
    "swim-turtle-story.html": {
      title: "The Swimming Boy Who Visited Sea Land",
      lead: "A story about Jiwoo, who loves swimming and travels to Sea Land with a turtle in his dream.",
      pages: [
        ["Jiwoo Loves Swimming", "Jiwoo loved stretching his arms in the water. At night, he held his swim goggles tight and fell asleep.", "Then the smell of the blue sea drifted softly into his dream."],
        ["The Turtle on the Moonlit Beach", "In his dream, Jiwoo stood on a shining beach. A green turtle lifted its head between the waves.", "\"Hello, Jiwoo. Do you want to visit Sea Land?\""],
        ["Through the Sea Gate", "Jiwoo gently climbed onto the turtle's back. Under the water, a pretty gate made of coral opened.", "\"Hold on tight. In Sea Land, everyone is a friend.\""],
        ["Colorful Fish Friends", "In Coral Square, yellow, blue, and orange fish were swimming. Jiwoo waved his hand.", "\"Swimming with you makes the sea feel like a rainbow!\""],
        ["The Octopus Painter's Colors", "A purple octopus was painting round pictures on a shell. The ink was not scary. It sparkled like beautiful color.", "\"In the sea, even waves can become pictures.\""],
        ["The Dolphins' Bubble Game", "Three dolphins made round bubble rings. Jiwoo and the turtle swam through the rings together.", "\"Ha ha! This is not a pool. It is a real sea playground!\""],
        ["Grandfather Whale", "In the deep blue water, a great whale slowly came closer. His eyes were kind like moonlight.", "\"Little friend, the sea likes a brave heart.\""],
        ["The Sea Land Festival", "Fish, octopus, dolphins, and whale all gathered. Shell bubbles floated up, and Coral Square glittered.", "Jiwoo swam in circles with his sea friends as if they were dancing."],
        ["Back to the Beach", "The turtle carried Jiwoo back to the moonlit water. The sea friends waved their tails from far away.", "\"Come again whenever your heart loves the water.\""],
        ["Morning Goggles", "In the morning, Jiwoo opened his eyes in bed. His blue goggles were in his hand, and Sea Land sparkled in his heart.", "That day at the pool, Jiwoo smiled brightly as he remembered his turtle friend."]
      ]
    },
    "seed-garden-story.html": {
      title: "The Little Gardener and the Sparkling Seeds",
      lead: "A story about caring for a tiny seed and learning to think of plants, friends, and neighbors.",
      pages: [
        ["Starlight on the Balcony", "Harin liked looking at the balcony flowerpots every morning. Today, a tiny light sparkled beside an empty pot.", "\"Is this a seed, or a little star?\" Harin gently held it in both hands."],
        ["A Soft Soil Blanket", "Harin filled a small pot with soft soil and laid the seed inside. She did not press too hard, but covered it warmly.", "\"Grow well. I will visit you every day.\""],
        ["Rolling Water Drops", "The next day, Harin watered it with a small watering can. As drops rolled over the soil, a pale green sprout peeked out.", "The sprout seemed to say, \"Thank you,\" to Harin."],
        ["A Glowing Flower Bud", "After days of sunlight and water, the sprout grew taller and taller. At the end of its stem, a flower bud glowed like a little lamp.", "Harin smiled quietly so the flower bud would not be startled."],
        ["The Morning Butterflies Came", "On a warm sunny morning, the flower bud opened wide. Yellow and blue butterflies fluttered lightly over the petals.", "Harin opened the balcony door a little so the butterflies could rest."],
        ["Thirsty Flowerpots", "That afternoon, the leaves in the next pots drooped. Harin learned that she should not care only for the sparkling flower.", "\"A garden is happy when everyone is healthy.\" Harin shared water with every pot."],
        ["Little Visitors", "Bees and ladybugs came after smelling the flowers. Harin did not reach out close. She watched quietly with her eyes.", "She learned that little visitors also have work to do in the garden."],
        ["The Flower's Gift", "At evening, the sparkling flower dropped tiny seeds from between its petals. The seeds glowed softly like stars in the night sky.", "Harin carefully put the seeds into small paper envelopes."],
        ["Seeds for Neighbors", "Harin gave seed envelopes to neighbors she met in the elevator. \"Plant them where sunlight comes in, and water them little by little.\"", "Small lights bloomed on the faces of the people who received the seeds."],
        ["Our Sparkling Neighborhood", "A few days later, little flowers bloomed on many apartment balconies. Harin's seeds became everyone's garden.", "Holding her watering can, Harin said, \"Even a small heart grows big when we share it.\""]
      ]
    },
    "dino-forest-story.html": {
      title: "The Little Expedition in Dinosaur Forest",
      lead: "A story about Junseo, who loves dinosaurs and helps a lost baby dinosaur.",
      pages: [
        ["Footprints in the Green Forest", "Junseo walked along the forest path holding his dinosaur book. Round footprints dotted the grass.", "\"Did a real dinosaur friend pass by?\""],
        ["The Baby Tricera", "Behind a giant fern, a baby tricera was sniffling. It had lost its way while looking for its mom.", "Junseo whispered, \"It's okay. I will help you.\""],
        ["A Leaf Map", "Junseo drew the forest path on a wide leaf. The baby dinosaur wiped its tears and brought its nose close to the map.", "The little expedition was ready to begin."],
        ["Following the Water Sound", "The two walked beside a babbling stream. They listened carefully for the sound of the mother dinosaur's steps.", "The forest did not feel scary. It felt like a friend hiding many clues."],
        ["Help from the Long-Neck Dinosaurs", "In a sunny clearing, long-neck dinosaurs were eating leaves. Junseo carefully walked over and asked for directions.", "A long-neck dinosaur pointed its tail toward the southern field."],
        ["Muddy Footprints", "Deep round footprints marked the muddy path. The baby tricera sniffed them and its eyes sparkled.", "\"Mom's footprints!\" Junseo was happy too."],
        ["Crossing the Stepping Stones", "A shallow stream blocked the way, but the two did not hurry. Junseo crossed first, and the baby dinosaur followed.", "When they waited for each other, even a hard path became easier."],
        ["A Shadow at the Edge of the Field", "At the end of the forest, a big tricera was standing. The baby dinosaur made a joyful sound and ran forward.", "Junseo's heart began to run with it."],
        ["A Warm Reunion", "The baby dinosaur tucked itself into its mother's arms. The mother dinosaur lowered her head as if thanking Junseo.", "Junseo waved and smiled brightly."],
        ["The Explorer Captain's Notebook", "Back home, Junseo drew the day's adventure in his dinosaur notebook. The biggest thing he drew was not the dinosaur, but the heart that helped a friend.", "On his next expedition, Junseo promised to notice his friends' feelings first."]
      ]
    },
    "magic-train-story.html": {
      title: "The Day Haram Built the Lightning Train",
      lead: "A story about Haram, who loves trains and learns patience while building a little train.",
      pages: [
        ["The Blue Train Blueprint", "Haram drew a wonderful train on paper. He colored round wheels and shiny windows.", "\"Today I am both the driver and the inventor!\""],
        ["A Bumpy First Start", "As soon as the train went onto the rail, it stopped with a bump. One wheel was a little crooked.", "Haram felt upset, but he decided to look again."],
        ["Setting the Wheels Straight", "Haram slowly fixed the wheels with a small toy tool. Because he did not rush, the train became straighter little by little.", "Time spent fixing was as important as time spent making."],
        ["Building Rails with a Friend", "His younger sibling brought blocks and made a long bridge. Haram connected a tunnel under the bridge.", "When they built together, the train track became much longer."],
        ["Success on the Bridge", "The blue train carefully climbed the bridge and passed through the tunnel. This time, it ran all the way without stopping.", "Haram lifted both hands high."],
        ["Making a Little Station", "Haram made a small station with blocks and placed toy passengers there. When the train arrived, everyone seemed ready for a trip.", "In the station of imagination, anyone could ride."],
        ["The Little Train Driver", "Haram stood tall like a driver and started the train. He handed out tiny tickets and began a family trip.", "\"The train to Imagination Land is leaving!\""],
        ["Starlight Road by the Window", "When the train passed the window, the room sparkled with starlight. Haram felt as if the train were running to Imagination Land.", "The little rail became a big dream road."],
        ["Everyone's Station", "The family sat around the train. Haram slowly stopped it and waited for the next passenger.", "A train he made alone became a game for everyone."],
        ["Next Station, Tomorrow", "At night, Haram fell asleep beside the train. The blue train sparkled softly and waited for tomorrow's trip.", "Haram learned that dreams can run when we do not give up."]
      ]
    },
    "space-soccer-story.html": {
      title: "The Soccer Match on the Moon",
      lead: "A story about Taeo, who loves soccer and learns teamwork with friends on the moon.",
      pages: [
        ["A Floating Soccer Field", "Taeo fell asleep hugging his soccer ball. In his dream, he opened his eyes on soft moon sand.", "Moon friends waved their hands and welcomed Taeo."],
        ["The Ball Flew Too High", "Taeo kicked the ball with all his strength, and it floated far above the goal. On the moon, even a soft kick sent the ball far away.", "Taeo laughed and decided to try again."],
        ["How to Kick Gently", "A small alien coach taught Taeo a soft toe kick. The ball glowed slowly as it rolled forward.", "In a new place, a new way was needed."],
        ["The First Pass", "Taeo did not run alone. He passed the ball to a friend beside him. The friend smiled brightly and passed it back.", "As the ball moved back and forth, their hearts grew closer."],
        ["Starlight Triangle Pass", "Taeo and his friends stood in a triangle and passed the ball. It floated along, leaving a tail of starlight.", "Watching friends mattered more than watching the goal."],
        ["The Friend Standing Alone", "Taeo saw a friend standing alone at the end of the moon field. The friend looked a little nervous that the ball might come.", "Taeo waved and invited the friend to join."],
        ["The Brave Pass", "Taeo kicked the ball very slowly. The shy friend received it and tapped it gently, and a smile bloomed on the friend's face.", "Waiting for a friend was also a wonderful play."],
        ["Toward the Goal", "When everyone worked together, the ball rolled slowly toward the goal. Instead of taking the last shot, Taeo looked at the friend beside him.", "This goal was made by everyone together."],
        ["Everyone's Goal", "The friend's kick sent the ball sparkling into the goal. Taeo and the moon friends floated up with joy.", "Because they scored together, they were even happier."],
        ["Morning Field", "In the morning, Taeo woke up hugging his soccer ball. That day on the field, he passed to a friend first.", "The teamwork he learned on the moon became Taeo's real skill."]
      ]
    },
    "tiny-firetruck-story.html": {
      title: "The Little Fire Truck Captain",
      lead: "A story about Minwoo, who loves fire trucks and calmly helps a friend.",
      pages: [
        ["Morning in the Red Helmet", "Minwoo put on his toy firefighter helmet and went to the park. From a tree, he heard a small kitten crying.", "\"The little rescue team is here!\""],
        ["Bbo-Bbo's Sparkling Signal", "Minwoo's little fire truck, Bbo-Bbo, sparkled. Its ladder was not long, but its wish to help was very big.", "Minwoo decided first not to scare the kitten."],
        ["A Cozy Blanket", "Minwoo spread a blanket under a low branch, just in case the kitten got startled while climbing down.", "Bravery began with a prepared heart."],
        ["A Small Voice", "Minwoo did not clap his hands. He spoke quietly. \"It's okay. You can come down slowly.\"", "The kitten's trembling tail slowly relaxed."],
        ["A Soft Landing", "The kitten tiptoed down onto the blanket. Minwoo did not shout. He smiled warmly.", "Bbo-Bbo blinked its little light with joy."],
        ["A Bowl of Water", "Minwoo placed a small bowl of water for the kitten. The kitten drank and sat quietly beside him.", "Rescue continued with care after the danger was over."],
        ["Goodbye, Kitten Friend", "The kitten walked toward the flower bed and looked back. Minwoo and Bbo-Bbo quietly waved.", "After helping, they waited so the kitten could leave in peace."],
        ["The Kindness Badge", "Minwoo put a small badge on his helmet. Today's badge was not for running fast, but for helping calmly.", "Minwoo felt very proud of that badge."],
        ["The Way Home", "As the sun went down, Minwoo carried his helmet and walked home. Bbo-Bbo rolled quietly beside him.", "The park felt a little warmer today."],
        ["Today's Rescue Captain", "Minwoo placed his helmet on the desk. Tomorrow, if someone needed help, he would look carefully first.", "The greatest fire truck was one that ran with a warm heart."]
      ]
    },
    "bug-detective-story.html": {
      title: "Taeo the Bug Detective",
      lead: "A story about Taeo, who loves insects and finds nature's secrets in the garden.",
      pages: [
        ["The Magnifying Glass Detective", "Taeo went out to the garden with a small magnifying glass. On the leaves, not a single sparkling drop of dew was left.", "\"Where did the dew go?\""],
        ["The Ladybug's Hint", "The ladybug gently opened its red wings and gave him a clue. When the sun came up, the dew sparkled and rose upward.", "Taeo looked up at the sky and found his first clue."],
        ["The Secret of the Ant Path", "The ants walked in a line, avoiding tiny drops of water. Taeo learned that insects notice even very small changes.", "The garden had many paths we could not see."],
        ["The Butterfly's Explanation", "The butterfly sat on a flower and said the dew had not disappeared. It had met the sunlight and gone on a journey.", "Taeo nodded and looked for the next clue."],
        ["The Morning of Little Friends", "A caterpillar and beetle moved slowly under a leaf. As the sunlight grew warmer, the dew became smaller.", "Taeo saw that nature changes quietly."],
        ["Dew Going to the Sky", "A tiny water drop at the tip of a leaf sparkled in the sunlight. Taeo felt as if the dew were rising into the sky.", "Even a small garden was a big science classroom."],
        ["A Drawing on the Soil", "With a twig, Taeo drew the dew's journey on the soil. His insect friends watched quietly from the leaves.", "Taeo began to understand the answer little by little."],
        ["A Small Cloud", "A white cloud floated above the garden. Taeo thought the dew might someday return as rain.", "It had not vanished. It was traveling."],
        ["The Sparkling Clue Returns", "The next morning, dew sparkled again on the leaves. The ladybug and beetle quietly welcomed the morning too.", "Taeo's guess was right."],
        ["The Bug Detective's Promise", "Taeo put down his magnifying glass and greeted his little friends. From now on, he would look at the garden more slowly and carefully.", "Taeo the bug detective found a heart that cares for nature too."]
      ]
    },
    "solar-system-story.html": {
      title: "The Sparkling Solar System Bus",
      lead: "A space-travel story about Haneul, who learns where each solar system friend belongs.",
      pages: [
        ["The Starlight Stop", "Haneul fell asleep hugging a paper rocket. In the dream, he opened his eyes to find a sparkling bus stop in the middle of space.", "“Welcome aboard the Solar System Bus!”", "Haneul read the tiny words on his ticket. “Meet every planet, and at the very end, find where our own home belongs.” He felt that this was not just a sightseeing trip, but a trip to learn about a promise."],
        ["The Warm Driver", "In the middle of the bus sat the Sun, the driver. The Sun lit up Haneul's seatbelt with a bright, gentle glow.", "The Sun was the center of the solar system family.", "The Sun driver told Haneul that the bus never wanders off just anywhere. Because the Sun shines from the center while the planet friends each follow their own path, the whole solar system stays steady and safe."],
        ["The First Guest, Mercury", "Tiny, speedy Mercury hopped on board with a whoosh. Haneul learned that Mercury spins fastest of all, close to the Sun.", "Even a small friend can be brave and strong.", "Mercury was so fast it made Haneul's hat flutter. Watching little Mercury take such pride in its job, Haneul thought that knowing your own place matters more than how big you are."],
        ["Venus in a Cloud Cape", "Venus wore a thick cloud cape and quietly took a seat. Haneul heard that Venus looks bright but is a very, very hot planet.", "You can't know a friend just by how they look.", "Venus gently shared the hot heart hidden behind its bright glow. Haneul nodded, trying to remember that even a friend who looks cheerful might have hard feelings deep inside."],
        ["Earth, the Blue Home", "Haneul looked out the window and saw blue Earth. With its oceans and clouds together, Earth was the precious home where Haneul lives.", "“Our home is part of the solar system family too.”", "When Earth came into view, Haneul suddenly thought of home. It felt so amazing that the sea, the forests, the clouds, and his family all live on one planet that he softly pressed his palm against the window."],
        ["Red-Sand Mars", "Mars greeted everyone wearing red sandy shoes. Haneul imagined that one day robot friends would find even more secrets on Mars.", "A curious heart can travel very far.", "Mars told Haneul about ancient water channels and exploring robots. Haneul learned that even when you don't have all the answers yet, a heart that keeps asking questions is what carries a science journey forward."],
        ["Great Big Jupiter", "When Jupiter climbed aboard, the seat creaked a little. Jupiter is the biggest planet, yet it kindly looked after its little moon friends.", "A heart bigger than its body shone brightest.", "Inside the bus, Jupiter made sure its little moon friends had their seats first. Haneul thought that maybe the biggest friend isn't the one who talks the loudest, but the one who looks after the most friends."],
        ["Saturn's Ring Music", "Saturn shook its sparkling rings and shared a song. Bits of ice and rock made soft ding-ding, tip-tap sounds.", "Different sounds became one song together.", "At first Saturn's ring sounds played all on their own, but when Haneul kept the beat, they flowed together like a song. The way the different sounds blended instead of fading made the whole bus quietly smile."],
        ["Far-Off Blue Friends", "Uranus danced lying on its side, and Neptune sent a letter on the blue wind. Haneul learned that far-away friends are part of the family too.", "Even far apart, friends who orbit together are family.", "Uranus and Neptune were so far away that their voices sounded small. Haneul came to understand that family isn't only the friends who are near; friends who circle the same path, even from far away, are part of the solar system family."],
        ["The Round-and-Round Promise", "When the trip ended, Haneul drew the solar system in his notebook. He also wrote down their promise to stay on their own paths around the Sun.", "That night, Haneul's room sparkled like a little solar system too.", "Haneul drew the Sun in the middle of his notebook and traced each planet's path in a circle. When the picture was done, the solar system looked less like a list of planets and more like one big promise to keep each other's places."]
      ]
    },
    "sun-story.html": {
      title: "The Warm Letter from the Sun",
      lead: "A story about Haneul, who follows the sun's light and warmth.",
      pages: [
        ["The Yellow Envelope", "By the morning window, Haneul found a yellow envelope. On it, shining words read, “From the Sun.”", "“Delivering today's warmth.”", "Haneul wondered why the letter had come to him. Inside the flap was the Sun's invitation: “Don't just receive the light, follow it and see where it goes.”"],
        ["Writing with Light", "When Haneul opened the envelope, sunlight letters spread across the room. The words drifted gently over the desk, the blanket, and a little flowerpot.", "Light is quiet, yet it reaches far.", "The sunlight writing didn't stop at brightening the room. It made dust specks sparkle and warmed the corner of a picture book, showing Haneul that light pays attention even to the smallest things."],
        ["When Plants Smile", "Haneul watched the leaves of a sunlit plant glisten. The little leaf lifted its head strongly, as if it had read the Sun's letter.", "Warm light gives the power to grow.", "Haneul moved the flowerpot to the window. Seeing the leaves lean slightly toward the light, he understood that the Sun's letter can be a gift like food for a plant."],
        ["The Shadow Friend", "When Haneul raised his hand, a shadow appeared on the wall. The Sun explained that wherever there is light, a shadow comes to play too.", "When you see light, you can understand shadows too.", "The shadow moved every time Haneul moved. The Sun told him that because light travels straight, a shadow forms behind things, and Haneul made a little bunny shadow with his fingers."],
        ["Too Close Gets Too Hot", "Haneul lifted a toy magnifying glass to gather sunlight, then stopped. The Sun's letter read, “Light must be handled with care.”", "Even warmth is best met safely.", "Haneul was surprised to hear that gathered sunlight can make paper hot. The Sun said that even though it is a warm friend, its light is powerful, so the wisdom to use it safely matters too."],
        ["The Great Power Inside the Sun", "In his dream, Haneul saw tiny flames inside the Sun joining hands. That power became light and heat and flew far away.", "The Sun was a great ball of fire that makes light.", "In the dream, the flames weren't bumping or fighting; they looked like friends gathering tiny bits of power to make one great light. Haneul imagined that even big energy comes from many small movements together."],
        ["The Path to the Planets", "The light letter passed Mercury, Venus, Earth, and Mars, and reached the farther planet friends too. Haneul's eyes sparkled, following the journey of the light.", "Even a single beam of light can take a long journey.", "The light reached the near planets first and traveled longer to arrive at the far ones. Haneul learned that even the same light brings a different timing and warmth to each friend."],
        ["Does the Sun Want to Rest Too?", "Haneul asked the Sun, “Doesn't shining every day make you tired?” The Sun smiled and said that sharing steadily is its own joy.", "When you steadily do what you love, your heart shines too.", "The Sun said it wasn't pretending never to rest; it was simply doing, again and again, what it can do from its own place. Haneul thought that even saying good morning each day could be a small light for someone."],
        ["The Sunset Reply", "When evening came, Haneul saw an orange sunset. As its day ended, the Sun had spread its last letter wide across the sky.", "The sunset was the Sun's gentle goodbye.", "The sunset was like a painting, leaving the day's path of light in color. Watching the sky blend orange, pink, and purple, Haneul thanked the Sun for all its hard work that day."],
        ["See You Again Tomorrow", "Haneul placed a reply by the window. “Sun, please shine safely again tomorrow.” The night sky quietly held that promise.", "When morning comes, the warm letter will visit again.", "After writing his reply, Haneul left the curtain open just a little. He felt that when the first sunbeam came in tomorrow morning, the Sun would be able to read his grateful heart."]
      ]
    },
    "mercury-story.html": {
      title: "Speedy Mercury's Errand",
      lead: "A story about Haneul, who learns to be careful alongside fast little Mercury.",
      pages: [
        ["Whoosh-Whoosh Sneakers", "In his dream, Haneul met Mercury wearing silver sneakers. Mercury was the messenger that circles the Sun the fastest of all.", "“Getting there fast is my specialty!”", "The moment Mercury saw Haneul, it handed over a little delivery bag. Inside was a packet of stardust to bring to the Sun, and a short note: “Go fast, but don't lose it.”"],
        ["The Path Near the Sun", "Mercury ran close to the Sun. Feeling how bright and hot the near path was, Haneul tied his hat strings tight.", "The closer you are, the more careful you must be.", "Haneul squinted in the very hot light. Mercury explained that being close to the Sun gives it wonderful speed, but it also feels the heat that much more strongly."],
        ["The Bumpy Ground", "Mercury's path had many little craters. Haneul heard that those craters were marks from collisions long ago.", "Even places that look like scars have a story.", "Each crater had its own shape and depth. At first Haneul thought it was just a bumpy road, but Mercury said those marks were the story of all the space it had endured for so long."],
        ["The Dropped Stardust", "Running too fast, Mercury dropped the stardust packet. Haneul said, “Let's stop for a moment and look for it.”", "Even a hurried heart needed a pause button.", "When the stardust packet fell, a flustered Mercury tried to run even faster. Haneul took Mercury's hand and said that when you're looking for something lost, slowing down can be the faster way."],
        ["Finding Little Footprints", "Haneul and Mercury walked slowly between the craters. Then they spotted the small sparkling footprints the stardust had left.", "Looking slowly, they could see the path better.", "The two followed the sparkling footprints and little by little their hearts grew calm. For the first time, Mercury heard the sound of its own steps and saw the small lights it had missed while racing."],
        ["The Hot Day", "Running toward the Sun, Mercury's daytime grew very hot. Haneul gripped his water bottle and found some shade to rest.", "Resting along the way is part of the journey too.", "In the hot day, even the strings on the stardust packet came loose. Tying them again in the shade, Haneul showed Mercury that taking time to fix your preparations is time that prevents failure."],
        ["The Cold Night", "When they crossed to the side away from the Sun, a cold night suddenly arrived. Haneul and Mercury pulled up a sparkly blanket and guarded the stardust packet.", "Even a small planet had big changes.", "When the cold night came, Mercury felt a little shy. It had only ever boasted about being a fast planet, but it realized that enduring the huge gap between day and night is an important part of who it is too."],
        ["A Careful Delivery", "This time Mercury ran fast but checked along the way. The packet reached the Sun's mailbox without being dropped even once.", "Speed and care ran together.", "At the Sun's mailbox, Mercury checked the packet twice. Haneul told Mercury that it hadn't become slow; it had become a smarter messenger who knows how to recognize the important moments."],
        ["Mercury's New Rule", "Mercury stuck a little star sticker on its sneakers. The sticker read, “Whoosh-whoosh, and check!”", "Adding a new habit to what you're good at makes you even better.", "The sneakers with the new rule sparkled more than before. Mercury proudly said, “Now I'm a friend who runs fast, and also a friend who knows how to stop.”"],
        ["Haneul's Errand", "When he woke in the morning, Haneul did his mom's errand, checking it carefully step by step. Fast like Mercury, but without missing a thing.", "That day, Haneul's steps felt sparkling and light too.", "At home, Haneul read the errand list out loud and put a check mark by each one. He had learned from Mercury that the joy of doing something properly lasts longer than just finishing it fast."]
      ]
    },
    "venus-story.html": {
      title: "The Secret of Venus in the Cloud Cape",
      lead: "A story about Haneul, who listens to the heart hidden inside Venus's clouds.",
      pages: [
        ["The Friend in the White Cape", "Haneul met Venus, wrapped in a snow-white cloud cape. Venus shone brightly, but seemed a little quiet.", "“I'm easy to see, but my heart is hard to see.”", "Haneul drew closer because Venus's bright glow looked lovely. But the more Venus was praised, the tighter it wrapped its cape, and Haneul grew curious about why."],
        ["The Sparkling Morning Star", "Venus shone very brightly in the dawn sky. Haneul said, “You're so pretty,” but Venus lowered its head a little.", "Even when you're praised, your heart can feel mixed up.", "Venus said that whenever it shone like the morning star, it felt like everyone expected something of it. Little by little, Haneul sensed that the word “pretty” alone cannot tell you everything about a friend's heart."],
        ["The Thick Cloud Door", "Haneul stepped close to the cloud cape. The clouds were so thick that he couldn't easily see inside.", "A heart you don't know can't be forced open.", "Before knocking on the cloud door, Haneul first asked, “Is it okay if I come in?” Venus nodded very slightly, and a narrow path opened between the clouds."],
        ["The Hot Heart Within", "Venus spoke carefully. “Inside me it's very hot. That's why no one can stay for long.” Haneul nodded.", "Even if you're bright on the outside, the inside can be hard.", "The hot air inside the clouds surprised Haneul. Venus said feelings held for a long time can get trapped and hot like this, and that it had wanted to speak but didn't know how to begin."],
        ["Listening Slowly", "Haneul listened to Venus without interrupting. Venus's clouds softened bit by bit, opening a small path of light.", "A heart that listens well makes the clouds lighter.", "Haneul didn't rush to offer a solution. Instead he answered slowly, “I see.” Venus felt relieved that someone was simply listening, not trying to fix its heart."],
        ["The Backward Spinning Greeting", "Venus turned slowly, in a slightly different direction from the other friends. Haneul said, “A greeting that spins differently is wonderful too.”", "Going a different way isn't being wrong.", "Venus admitted it had felt shy about being the only one turning the other way. Haneul told Venus that its slow greeting, spinning in a different direction, was as elegant as a dance at a ball."],
        ["A Drawing in the Clouds", "Haneul drew a little heart on top of the clouds. For the first time, Venus smiled and gave the edge of its cape a small wave.", "Even a small gesture can share what's in your heart.", "The heart Haneul drew soon became a little window in the clouds. Through that window Venus saw its friends' faces and learned that it could show its heart bit by bit without taking off its whole cape."],
        ["Telling the Friends", "Venus shared its story with the solar system friends. “I am a friend who is bright and hot, and a little shy.”", "Speaking its true self made its heart lighter.", "The solar system friends listened to Venus quietly. No one called Venus strange, and instead of a loud cheer, Jupiter gave a very gentle round of applause."],
        ["A Softer Light", "That evening, Venus shone more softly in the sky. Haneul felt that Venus's light was not only pretty, but brave.", "Courage begins with showing what's in your heart.", "Venus's light was as bright as before, but to Haneul it felt different now. For inside that light there was also the courage of someone who had moved past their shyness to tell their own story."],
        ["My Own Cape", "When he woke in the morning, Haneul decided to try speaking his heart too. On shy days, he would say, “Right now my heart is feeling a little hot.”", "Venus taught Haneul how to put his heart into words.", "Haneul decided to think of Venus on days when his feelings were hard to share. Because rather than hiding your heart away, telling a little to someone you trust can make even a cloud cape feel lighter."]
      ]
    },
    "mars-story.html": {
      title: "The Seed on Red-Sand Mars",
      lead: "A story about Haneul, who plants a little hope on Mars.",
      pages: [
        ["Red Sandy Shoes", "In his dream, Haneul arrived on Mars wearing red sandy shoes. Under his feet came tiny crunch-crunch sounds.", "“This is Mars, the red planet.”", "Looking out over Mars's red hills, Haneul felt a little lost. No matter where he looked there was no water or trees, but Mars quietly said, “There are still many stories to find here.”"],
        ["The Little Explorer Robot", "Over a Martian hill, a little explorer robot beeped hello. The robot showed Haneul a map of an ancient valley.", "A curious heart moved a robot friend too.", "The explorer robot moved very slowly, but it never gave up. Following the robot's wheel tracks, Haneul learned that exploring isn't about running fast; it's about looking carefully, again and again."],
        ["The Dry Valley", "Haneul walked along the valley. The robot told him that long, long ago, water may have flowed here.", "Even a dry path holds an old story.", "On the valley walls were stripes that looked as if water had passed through. Haneul found it amazing that, through traces, you can imagine and ask questions even about things you can no longer see."],
        ["The Seed in His Pocket", "A tiny seed came out of Haneul's pocket. On the red sand, the seed seemed to ask, “Can I grow here too?”", "Haneul gently cupped the seed in his hands.", "The seed was like a little visitor from Earth. Haneul didn't promise Mars he would surely grow it big; instead he said he would start with the care he could give today."],
        ["Sparkling Ice", "In a shady spot, the robot found a small piece of ice. Haneul gathered sunlight in his palm to melt the ice into a drop of water.", "Even a single drop of water was a precious gift.", "The ice melted very slowly on his palm. Letting one drop fall onto the soil, Haneul felt that even a small help, when it reaches the place that needs it, becomes something big."],
        ["Building a Stone Wall", "Haneul and the robot built a little stone wall around the seed. So that even when the red wind blew, the seed wouldn't fly away.", "Hope can only grow when it meets care.", "Building the stone wall took longer than expected. While the robot carried stones and Haneul fit them into place, Mars lowered its red wind for a while to help the two of them."],
        ["The Dust Storm", "Suddenly a dust storm rolled in. Together with the robot, Haneul guarded the seed and sang in a low voice.", "Even a scary wind can be endured when you're together.", "In the dust storm it was hard to see ahead. Haneul was scared, but he didn't run away and leave the seed; following the robot's little light, he crouched low beside the stone wall."],
        ["A Single Green Dot", "After the storm passed, a tiny green dot rose up among the red sand. Haneul held his breath and gazed at it.", "“It's small, but it's a real sprout!”", "The green dot was so tiny, even smaller than a fingernail. Still, seeing it made Haneul so happy he could have cried, and after a long silence, Mars let out a very soft little laugh too."],
        ["Mars's Smile", "Mars smiled, lighting up its red hills brightly. One little sprout had made the cold scenery a little bit warmer.", "Hope can begin with even the tiniest bit of color.", "Mars said the sprout wouldn't turn it into a garden all at once. But it said that one green dot born today could call forth another question and more care tomorrow."],
        ["The Red Notebook", "When he woke in the morning, Haneul drew the seed in his red notebook. Then he shared a cup of water with his own flowerpot too.", "The care Haneul learned on Mars grew in his room too.", "In his red notebook, Haneul wrote, “Hope isn't shouting out loud; it's giving water every day.” Then, looking at the flowerpot in his room, he quietly said hello to Mars's little sprout too."]
      ]
    },
    "jupiter-story.html": {
      title: "Big Jupiter's Red Spot",
      lead: "A story about Haneul, who meets Jupiter's big heart and its old storm.",
      pages: [
        ["The Big Striped Friend", "Haneul met Jupiter, whose striped clouds swirled round and round. Jupiter was so big that Haneul had to tip his head way back to see.", "“I'm big, but I want to be your friend.”", "Jupiter was so huge that at first Haneul felt a little scared. But instead of a giant hand, Jupiter let down a soft ladder of clouds, so even a small friend could climb up easily."],
        ["The Secret of the Red Spot", "There was a big red spot on Jupiter's face. Haneul heard that an old storm was spinning around inside it.", "Even a big, strong friend can feel stormy sometimes.", "The red spot wasn't a quiet pattern. It was a storm that had been spinning for a long, long time. Jupiter said everyone likes to look at his pretty stripes, but some days this storm makes his heart feel heavy."],
        ["The Sound of the Swirl", "Near the red spot, the wind made a deep rumbling sound. Haneul felt a little scared, but he held Jupiter's hand tight.", "When you're scared, it's okay to hold someone's hand.", "The swirling sound wasn't Jupiter being angry. It was an old wind still searching for its way, and Haneul told Jupiter he didn't have to bear that sound all alone."],
        ["The Little Moons Say Hello", "Many moon friends lived beside Jupiter. Io, Europa, Ganymede, and Callisto twinkled hello to Haneul.", "Jupiter held many friends close.", "The moon friends were a little scared of Jupiter's storm, but they never left his side. Haneul saw that even when friends can't fix a problem, just being there helps a heart grow wider."],
        ["Giving the Storm a Name", "Haneul said to Jupiter, “What if we call your red spot the old wind friend?” Jupiter slowly said the words too.", "Naming a feeling makes it easier to look at.", "At first Jupiter thought it was strange to name a storm. But once he called it “the old wind friend,” the storm felt less like an enemy and more like a feeling he could understand."],
        ["Taking a Big Breath", "Jupiter and Haneul took big breaths together, one, two, three. The red spot didn't go away, but its sound grew a little softer.", "A breath can rock a heart gently calm.", "While they breathed, Haneul watched Jupiter's cloudy stripes move slowly. The wind kept spinning, but Jupiter's face looked a little less tense than before."],
        ["The Moon Friends' Song", "The moon friends sang a little song. “Jupiter, your wind is part of your heart too.” Jupiter's eyes sparkled.", "A friend's song wrapped a big heart in a hug.", "The moon friends' song was softer than the storm, but Jupiter heard it even better. When the song ended, Jupiter pointed at his red spot and said for the first time, “This is part of me too.”"],
        ["Painting the Cloud Stripes", "Haneul painted along Jupiter's cloudy stripes. In the picture, the red spot looked like a round flower.", "Seen a new way, even a scary thing can look new.", "Haneul painted the red spot like a flower, and the moon friends drew little stars all around it. Jupiter watched his hard feeling turn into a warm story inside the picture."],
        ["The Big-Hearted Hug", "Jupiter wrapped the moon friends and Haneul in his wide, cloudy arms. Even with the storm, his warm hug stayed just the same.", "A big heart can hold even its own storms.", "Instead of hiding everyone behind his huge body, Jupiter made room for each one to shine. Haneul thought a big heart isn't about looking big yourself, but about helping the little friends beside you be seen."],
        ["Haneul's Red Spot", "When Haneul woke up, he drew his upset feeling as a red spot. Next to it he wrote, “It's okay, this is my heart.”", "Jupiter showed Haneul how to care for his feelings.", "On the day Haneul drew his red spot, the upset feeling didn't disappear, but it wasn't only scary anymore. Just as Jupiter taught him, when you name a feeling and look at it, it becomes a story you can handle."]
      ]
    },
    "saturn-story.html": {
      title: "Saturn's Ring Concert",
      lead: "A story about Haneul, who learns the beauty of many different sounds in Saturn's rings.",
      pages: [
        ["The Sparkling Ring Invitation", "On his desk, Haneul found an invitation shaped like a ring. It read, “Please come to Saturn's ring concert.”", "Haneul set off with his space music sheet in hand.", "Haneul carried the invitation to Saturn, but he was worried because he couldn't read music very well. Saturn told him that at a ring concert, listening to each other matters more than playing perfectly."],
        ["The Ice-Chip Violins", "Little chips of ice sparkled in Saturn's rings. The ice chips played a clear, ringing violin sound.", "Even a tiny chip can make a pretty sound.", "Each time sunlight touched the ice chips, they sang at different pitches. Listening to the clear notes, Haneul thought that even cold ice can feel like warm music when it meets the light."],
        ["The Pebble Drums", "The round pebbles played a bouncy drum beat. Haneul tapped his knees with his palms to keep the rhythm.", "Different sounds made a rhythm together.", "The pebble drums were deeper than the ice violins. At first they seemed to stick out too much, but Haneul learned that without that drumbeat, the music would have no footsteps to walk on."],
        ["The Dust-Speck Shakers", "The tiny specks of dust became soft little shakers. They were so small they were hard to hear, but the music felt empty without them.", "Even a small voice is part of the music.", "The dust-speck sound was so tiny that everyone often missed it. Haneul leaned his ear closer and discovered that the little swishing added a sparkling breath to the ring music."],
        ["The Messy First Rehearsal", "At first, everyone played whatever they wanted. Haneul covered his ears, then laughed and said, “Let's listen to each other!”", "To play together, you have to listen first.", "When the rehearsal grew noisy, some ring pieces wanted to stop making their sound. Haneul said that everyone going silent wasn't the answer, and that finding your turn is the way to play together."],
        ["Saturn's Slow Beat", "Saturn turned the rings slowly to show the beat. Ding-ding, pat-pat, swish-swish, the sounds slowly found their places.", "When you match slowly, your hearts match too.", "Saturn made the first beat by turning the rings slowly. As ice, stone, and dust followed that beat, Haneul could hear all the tangled sounds finding their way."],
        ["Haneul's Conductor's Baton", "Haneul picked up a starlight baton. As he called out the loud and soft sounds in turn, the ring music grew richer.", "There was a turn for everyone to be the star.", "Haneul's baton wasn't a stick for bossing anyone around. It was like a guide, calling back the friends whose sounds had grown quiet, and gently lowering the ones that were too loud."],
        ["The Planet Audience", "Jupiter, Uranus, and Neptune came from far away to hear the music. Saturn felt shy, but proudly spread its rings wide.", "Showing your own true self is a wonderful thing.", "When the planet audience arrived, Saturn paused, worried its rings might look strange. Haneul said Saturn's rings were exactly its own special stage, and helped it spread them even wider."],
        ["The Song That Spread Through Space", "The ring music spread far across space. Haneul learned that the sounds sparkled even more because they were all different.", "When differences come together, the song is more beautiful.", "As the music spread, Haneul heard that each sound stayed just as it was. They hadn't all become the same sound; instead they had become a song that shone together by listening to one another."],
        ["The Round Promise", "When Haneul woke up, he decided to wait for the quiet voices when singing with friends. He wanted to hold everyone, just like Saturn's rings.", "That day, a little concert was held in Haneul's classroom too.", "Haneul wanted to make a place where both loud and soft sounds could fit, just like the rings of Saturn. So in class, he stood beside the friend with the smallest voice and waited for them to sing."]
      ]
    },
    "uranus-story.html": {
      title: "The Dance of Tilted Uranus",
      lead: "A story about Haneul, who finds his own direction together with Uranus.",
      pages: [
        ["The Pale Blue Ice Stage", "Haneul met Uranus on a stage of soft blue light. Unlike the other friends, Uranus spun while lying on its side.", "“Does my dance look a little strange?”", "Haneul wondered why Uranus kept standing at the edge of the stage. Uranus was worried that its tilted shape might mess up the round dance of the other friends."],
        ["The Tilted First Greeting", "Uranus tilted its body to say hello. It was a greeting Haneul had never seen, so he was surprised, but soon he tried it too.", "A new kind of greeting brought laughter.", "Haneul almost tumbled over while copying Uranus's tilted bow. They both laughed, and for the first time Uranus felt that its greeting could bring someone joy."],
        ["A Worry About Going a Different Way", "Uranus said softly, “Everyone seems to spin upright, so why do I spin on my side?” Haneul listened slowly.", "A different shape has its own reason and story.", "Uranus said that maybe a big change long ago left it tilted the way it is now. Hearing this, Haneul thought that a different shape isn't just for fun; it can hold the time it has lived through."],
        ["The Blue Ribbon Shadow", "When Uranus spun, it cast a shadow like a long blue ribbon. Haneul said the shadow was as beautiful as a stage decoration.", "Moving differently, a different beauty appeared.", "The blue ribbon shadow changed shape every time Uranus moved. Haneul said it was a stage decoration only Uranus could make, and he stuck star stickers along the shadow."],
        ["The Little Moons' Applause", "The little moons beside Uranus clapped. “We love your sideways spinning dance!” Uranus's face lit up.", "A close friend's cheer becomes great strength.", "The little moons' applause wasn't loud, but it was steady. Listening to it, Uranus decided to trust the cheers of close friends first, before being understood by everyone."],
        ["Haneul's Wobbly Dance", "Haneul danced all wobbly on purpose. It wasn't perfect, but Haneul laughed out loud.", "In a happy dance, every way can be right.", "Haneul's dance had arms and legs going every which way. Still, he laughed and said, “My dance is mine too,” and those words stayed in Uranus's heart for a long time."],
        ["A Sky That Opens Sideways", "Uranus spun with more confidence. Then its blue light spread out sideways and opened like a wide door in space.", "When you trust your own direction, a new path opens.", "When Uranus spun with confidence, a door of blue light swung wide open. Beyond it lay a view showing that not only straight paths, but tilted paths too, can become an adventure."],
        ["Long, Slow Seasons", "Uranus said that because of its tilted body, its seasons pass in a very special way. Haneul's eyes sparkled as he imagined the long seasons.", "A special direction makes a special kind of time.", "Hearing about the long seasons, Haneul felt that changing quickly isn't always better. A season that stays a long time can teach you a heart that observes slowly and waits."],
        ["My Very Own Spin Name", "Uranus gave its dance a name, “the Blue Sideways Spin.” Haneul wrote the name in big letters in his space notebook.", "Giving it a name makes who you are more precious.", "Once it had the name Blue Sideways Spin, Uranus's dance was no longer an embarrassing mistake. Haneul thought that a single name can become a little flag that protects who you are."],
        ["Haneul's Direction", "When Haneul woke up, he thought it was okay to choose a different color from his friends when drawing. He decided to trust his own direction, just like Uranus.", "Haneul's picture was special too, like the Blue Sideways Spin.", "When Haneul picked a different color from his friend, he didn't rush to change it like before. Just like the Blue Sideways Spin that Uranus showed him, he knew his own direction makes a picture richer."]
      ]
    },
    "neptune-story.html": {
      title: "Neptune's Blue Wind Post Office",
      lead: "A story about Haneul, who learns how to send his heart all the way to faraway Neptune.",
      pages: [
        ["The Farthest Post Office", "Haneul met Neptune in front of a blue mailbox. Neptune was a friend who sent wind letters from the very far edge of the solar system.", "“Even far away, I can still send my heart.”", "Haneul felt a little lonely because Neptune's post office was so quiet. Neptune said honestly that, being such a faraway friend, it was often hard to be the first to speak."],
        ["The Quick Blue Wind", "Neptune's wind was very fast. When it whooshed off carrying a letter, even Haneul's hair fluttered a little.", "A fast wind needs a careful hand.", "The blue wind wanted to send the letters quickly, so it kept blowing too hard. Haneul said that the more you rush, the more a letter can get crumpled, so he decided to teach the wind how to breathe slowly."],
        ["The Too-Strong First Delivery", "The first letter blew so hard it tickled Saturn's rings. Surprised, Neptune tied its wind sack up tight.", "“When the heart is in a hurry, even a letter can get startled.”", "When Saturn's rings wobbled, Neptune's face turned even bluer. But Haneul told it that trying to send gently again mattered more than the fact that it had made a mistake."],
        ["Gentle Practice", "Haneul folded Neptune a paper airplane. “What if you push it softly, like this?” Neptune blew the wind gently.", "A soft force can travel far too.", "A paper airplane thrown hard wobbled before it could go far. Haneul and Neptune folded and flew it again and again, until they found a wind that was gentle but just right."],
        ["The Cold Blue Light", "Being far away, Neptune glowed cold and blue. Even wearing warm gloves, Haneul felt that its light was beautiful.", "Even a cold place can hold a warm heart.", "At first Neptune's cold light looked lonely, but up close it was calm like a deep sea. Haneul felt that warmth doesn't always come in hot colors."],
        ["Writing the Friends' Names", "Haneul and Neptune wrote the planet friends' names on the letter, one by one. Mercury, Venus, Mars, Jupiter, Saturn, even Uranus.", "While writing their names, the friends grew closer.", "While they wrote each friend's name, Neptune's post office seemed to grow a little busier. When you call a name, even a faraway friend takes a place in your heart."],
        ["The Wind-Path Map", "Neptune unrolled a map of blue wind paths. Haneul marked the routes between the stars so the letters wouldn't bump into anything.", "To deliver well, you need a heart that watches the way.", "The wind-path map even marked the empty spaces between the stars and planets. Haneul learned that watching the path a letter takes is the first step in caring for the friend who receives it."],
        ["A Quiet Arrival", "This time the letters settled quietly in front of each friend's window. Jupiter smiled, Saturn shook its rings, and Uranus danced sideways.", "A gentle letter made everyone smile.", "The quietly arriving letters didn't startle the friends. Jupiter wanted to write back in big letters, but thinking of Neptune, it wrote slowly and neatly."],
        ["The Night the Replies Came Back", "As night grew deep, replies arrived one by one at Neptune's post office. Even far away, Neptune wasn't lonely anymore.", "A heart that gives and receives crosses any distance.", "When the replies came back, Neptune stood in front of the mailbox for a long time. It was still far away, but the letters going back and forth filled Neptune's night with light."],
        ["Haneul's Postcard", "When Haneul woke up, he wrote a postcard to a friend who lives far away. “I miss you. But we're still friends.” Neptune's wind seemed to smile a little.", "Even the farthest friend grows close when you send your heart.", "Before sticking on the stamp, Haneul read the postcard one more time. Just as Neptune taught him, sending your heart is less about how fast it goes and more about how kindly it arrives."]
      ]
    },
    "angry-balloon-story.html": {
      title: "When Anger Puffs Up Like a Balloon",
      lead: "A story about Toto the squirrel, who learns how to calm his heart when he feels angry.",
      pages: [
        ["A Red, Red Face", "Toto's tower of acorns came tumbling down, and his face turned bright red. Something puffed up inside his chest, like a balloon.", "“Ugh, I'm so angry!”"],
        ["The Anger Balloon Grows", "When Toto got angry, a red balloon swelled bigger and bigger inside him. When it grew too big, he stomped his feet.", "The balloon just kept puffing up and up."],
        ["Mom's Little Secret", "Mom squirrel came close and spoke softly. When you're angry, she said, you can let the air out of the balloon slowly.", "“Let's breathe out, nice and long.”"],
        ["One Deep Breath", "Toto breathed in through his nose and out through his mouth. One, two, three breaths, and the balloon grew a little smaller.", "“Oh? My chest feels lighter now.”"],
        ["One, Two, Three", "Mom told him to count the numbers in his heart. As he counted one, two, three, the anger slowly settled down.", "The more he counted, the smaller the balloon became."],
        ["Saying How I Feel", "Toto said, “I was sad because my tower fell.” When he put his feelings into words, the tightness melted away.", "“I wasn't really angry. I was just sad.”"],
        ["The Smaller Balloon", "The big red balloon shrank until it was small as his palm. And Toto's face turned soft and calm again.", "He didn't need to stomp his feet anymore."],
        ["Stacking Again, One by One", "Toto began to stack the fallen acorns again, one by one. Going slowly, the tower grew even stronger.", "Once his anger calmed, a good idea came to him."],
        ["A Tower Built Together", "A friend passing by helped him place the acorns on top. The tower they made together was the tallest and finest of all.", "“It's more fun when we do it together!”"],
        ["When I Feel Angry", "Now when his anger balloon puffs up, Toto breathes out slow. Because he knows the balloon will shrink down again.", "“Breathe out. One, two, three. I'm okay now.”"]
      ]
    },
    "dokkaebi-club-story.html": {
      title: "The Goblins' Magic Club",
      lead: "An old tale about an honest woodcutter who comes to win a goblins' magic club.",
      pages: [
        ["The Kind Woodcutter", "Long ago, a kind-hearted woodcutter lived deep in the mountains. As he chopped wood, he picked up the fallen hazelnuts one by one.", "“This one's for my parents, and this one for my child.”"],
        ["An Empty House at Dusk", "When night fell, the woodcutter went into an empty mountain house to rest. Soon he heard murmuring voices outside.", "“Who could be coming?”"],
        ["The Goblins' Feast", "A band of goblins crowded into the house and pounded their magic clubs. “Gold, come out!” they shouted, and gold truly poured out.", "“Wow, treasure comes out of those clubs!”"],
        ["Crack! A Hazelnut", "Hiding in the corner, the woodcutter bit down on a hazelnut by accident. The loud crack made the goblins think the house was falling down.", "“Yikes, the house is collapsing!”"],
        ["The Club Left Behind", "The goblins dropped their club and scrambled away in a panic. All alone in the empty house sat one magic club.", "“The club is still right here.”"],
        ["Back Home Again", "The woodcutter carried the club home, careful every step. But he wasn't greedy, so he used only what he truly needed.", "“I'll borrow just as much as I need.”"],
        ["Sharing with Neighbors", "With the club he made rice and warm blankets for his poor neighbors. Warm laughter spread all through the village.", "“Sharing together makes me even happier!”"],
        ["A Greedy Neighbor", "A greedy neighbor saw this and went to the empty house on purpose. All he wanted was to grab the magic club for himself.", "“I'll take a whole pile of treasure too!”"],
        ["The Lie Is Found Out", "This time the goblins weren't fooled and saw through the lie. The greedy neighbor went home empty-handed, with no treasure at all.", "“You can't get treasure with lies.”"],
        ["An Honest Heart Is the Treasure", "The kind woodcutter was blessed for his honest, sharing heart. The real treasure isn't greed, but a warm and giving heart.", "“When you're honest, good fortune finds you!”"]
      ]
    },
    "earth-letter-story.html": {
      title: "A Note from the Earth",
      lead: "A story about Hansol, a child who learns to care for nature after a little note from the Earth.",
      pages: [
        ["A Note on a Leaf", "In the park, Hansol found a tiny note resting on a leaf. It said it was a letter sent by the Earth.", "“Who could have sent this letter?”"],
        ["The Earth Says Hello", "The note said, “Hello, I am the Earth where you all live.” It told him the Earth was feeling a little tired.", "“The Earth wrote a letter to me?”"],
        ["Scattered Trash", "Looking around, Hansol saw trash scattered all over the park. Now he understood why the Earth felt so tired.", "“So this is what wore the Earth out.”"],
        ["Picking Up, One by One", "Hansol took a bag and picked up the trash one piece at a time. His hands were small, but they worked hard without stopping.", "“I'll help you, Earth!”"],
        ["Sorting It Out", "Hansol sorted the cans, paper, and plastic into different bags. He had learned that sorting well lets things be used again.", "“This one can be born all over again!”"],
        ["Friends Pitch In", "Friends walking by came to help Hansol clean up too. With many hands together, the park was soon spotless.", "“It's so much faster together!”"],
        ["Planting a Little Tree", "The children planted one small tree in the empty flower bed. The tree would give them fresh, clean air.", "“Grow big and strong!”"],
        ["The Friends Return", "Once the park was clean, the birds and butterflies came back. Living things gathered in the bright, fresh place.", "“The birds are singing again!”"],
        ["Thank You, Says the Note", "A new note lay gently on a leaf. It said, “Thank you. Now I feel strong again.”", "“The Earth is smiling!”"],
        ["A Heart That Cares for the Earth", "Hansol learned that small actions keep the Earth healthy. From now on, he would always throw trash where it belongs.", "“When we protect it, the Earth smiles too!”"]
      ]
    },
    "first-school-day-story.html": {
      title: "The First Walk to School",
      lead: "A story about Bori the baby bear, on a first school day full of excitement and a little fear.",
      pages: [
        ["A Fluttery First Day", "Baby bear Bori put on his new backpack and stood in front of the mirror. Today was his very first day of school.", "“I'm excited, but a little nervous too.”"],
        ["Walking with Mom", "Mom bear held Bori's hand, warm and gentle. Yellow dandelions bloomed along the way to school.", "“Mom believes you'll do just fine.”"],
        ["The Big School Door", "The school door looked far bigger than Bori. He stopped in his tracks for a moment in front of it.", "“Who could be inside?”"],
        ["A Smiling Teacher", "Inside the door, Teacher Rabbit greeted him with a bright smile. Her warm voice put Bori's heart a little more at ease.", "“Welcome, Bori. I've been waiting for you.”"],
        ["New Friends", "In the classroom were a fox, a raccoon, and a hedgehog. They all looked a little nervous, just like Bori.", "“So I wasn't the only nervous one.”"],
        ["Hello, Seatmate", "The hedgehog beside him said his name first. Bori found his courage and said hello back.", "“Hi, I'm Bori. Let's play together.”"],
        ["A Song for Everyone", "The teacher clapped her hands and taught them a song. Singing it all together, the classroom filled with joy.", "His nervous feelings melted into the song."],
        ["The Fun Playground", "At recess they played tag on the playground. Bori ran around with his friends, giggling all the way.", "“I didn't know school could be this fun!”"],
        ["See You Tomorrow", "Before he knew it, it was time to go home. Bori waved goodbye to all his new friends.", "“See you tomorrow! It's a promise!”"],
        ["I Did Great Today", "Back home, Bori spilled out the whole day's story to Mom. The first day was nerve-racking, but truly wonderful.", "“Mom, I can go to school!”"]
      ]
    },
    "honest-rabbit-story.html": {
      title: "Kongi the Rabbit's Honest Day",
      lead: "A story about Kongi the rabbit, who tells a little lie and learns the power of being honest.",
      pages: [
        ["Crash! The Vase", "Kongi the rabbit was playing in the living room when she broke a vase. The crash made her jump with fright.", "“Oh no, what do I do? If Mom finds out…”"],
        ["Hiding It Away", "Kongi quietly tucked the broken pieces behind the curtain. She thought no one would ever know.", "“I'll just say it wasn't me.”"],
        ["Mom's Question", "Mom rabbit saw the empty spot and asked who did it. Kongi answered in a tiny voice, “Not me.”", "But her heart went thump, thump, and grew heavy."],
        ["A Heavy Heart", "After telling the lie, even playing wasn't fun anymore. It felt like a little stone had settled in her heart.", "“Why does my heart keep aching?”"],
        ["A Sleepless Night", "Even when night came, Kongi couldn't fall asleep. The lie kept poking at her heart.", "“I wish I had just told the truth.”"],
        ["Finding Courage", "The next morning, Kongi found her courage and went to Mom. With a shaky voice, she decided to tell the truth.", "“Mom, the truth is, I broke the vase.”"],
        ["Thank You for Being Honest", "Mom didn't get angry. She wrapped Kongi in a big hug. She said thank you for telling the truth.", "“Everyone makes mistakes. Thank you for telling me.”"],
        ["A Lighter Heart", "Once she told the truth, the stone in her heart was gone. Kongi's chest felt as light as a feather.", "“My heart doesn't hurt at all now!”"],
        ["Fixing It Together", "Kongi and Mom planted a flower in a new pot together. Telling the truth and fixing it together felt even better.", "“Next time I'll be careful when I run.”"],
        ["Honest Is the Easiest Way", "Kongi learned that her heart feels best when she's honest. Now she tells the truth, even about little things.", "“Being honest makes my heart sparkle!”"]
      ]
    },
    "keeping-promise-story.html": {
      title: "The Day a Promise Was Kept",
      lead: "A story about Kongkong the puppy, who keeps a small promise and learns how precious trust can be.",
      pages: [
        ["A Pinky Promise", "Kongkong the puppy hooked pinky fingers with his friend the squirrel. They promised to meet on the hill tomorrow morning.", "“We'll really meet, okay? Promise!”"],
        ["A New Toy Arrives", "The next morning, a wonderful new toy arrived at Kongkong's house. He was so excited he nearly forgot the promise.", "“Wow, this is the one I really wanted!”"],
        ["What Should I Do?", "He wanted the toy, but the promise with his friend came to mind too. Kongkong fell into a moment of worry.", "“The toy? Or the promise?”"],
        ["A Friend Waiting", "Kongkong pictured the squirrel waiting all alone on the hill. If he broke the promise, his friend would surely be sad.", "“The squirrel must be waiting just for me.”"],
        ["Kongkong Chooses the Promise", "Kongkong gently set the toy down and headed out the door. A promise, he thought, is more precious than any toy.", "“The toy can wait! The promise comes first.”"],
        ["Toward the Hill", "Kongkong ran with all his might so he wouldn't be late. He raced up to the hill, slicing through the wind.", "“Wait for me, I'm coming!”"],
        ["A Happy Face", "On top of the hill, the squirrel was waiting with a bright smile. The moment he saw Kongkong, he hopped for joy.", "“I knew you'd come! Thank you, Kongkong.”"],
        ["Fun on the Hill", "The two rolled and tumbled down the hill, playing happily. Keeping the promise made it a wonderful day.", "“I'm so glad I came after all!”"],
        ["Trust Has Grown", "The squirrel said he trusted Kongkong even more now. Keeping the promise made their friendship stronger.", "“When I make a promise with you, my heart feels safe.”"],
        ["A Promise Is Precious", "Kongkong learned that keeping a promise earns a friend's trust. He decided to keep every promise, even the small ones.", "“I'll keep our next promise too!”"]
      ]
    },
    "morning-routine-story.html": {
      title: "Ttotto's All-By-Myself Morning",
      lead: "A story about Ttotto the baby penguin, who dawdled every morning and learns the joy of doing things by himself.",
      pages: [
        ["A Slow, Dawdling Morning", "Baby penguin Ttotto dawdled under his blanket every morning. He kept putting off getting up and getting ready.", "“Just a little more sleep…”"],
        ["The Morning Chart", "Mom penguin showed him a morning chart full of pictures. For each thing he finished, he could stick on a star.", "“Why don't you try doing it yourself?”"],
        ["First Star: Waking Up", "Ttotto stretched way up and got out of bed all by himself. He stuck the very first star on his chart.", "“I did one! One shiny star!”"],
        ["Brush, Brush, Brush", "In front of the mirror, Ttotto brushed his teeth up and down. His mouth felt fresh, and so did his mood.", "“The second star is mine too!”"],
        ["Dressing Myself", "Ttotto put on his clothes, buttoning them one by one. It was tricky at first, but his hands got quicker and quicker.", "“I buttoned them all by myself!”"],
        ["A Hearty Breakfast", "Ttotto sat at the table and ate a bit of everything. With a full belly, his energy came bursting up.", "“Fourth star, breakfast done!”"],
        ["Packing My Own Bag", "Ttotto gathered what he needed and tucked it all into his bag. He checked one more time that nothing was missing.", "“I packed everything myself!”"],
        ["Full of Stars", "Before he knew it, his chart was full of stars. Ttotto felt so proud of all he had done by himself.", "“I did it all on my own!”"],
        ["Mom's Praise", "Mom hugged Ttotto tight and told him how wonderful he was. Ttotto's shoulders rose with pride.", "“Doing it myself even gives me more time!”"],
        ["Ttotto the Can-Do Penguin", "Now Ttotto gets ready all by himself every morning. He never knew doing things on his own could be so much fun.", "“All set today! I'm off, see you later!”"]
      ]
    },
    "new-friend-story.html": {
      title: "The Day I Made a New Friend",
      lead: "A story about Byeoli, a little deer who learns the courage to reach out first.",
      pages: [
        ["A New Town", "Byeoli the little deer had just moved to a new town. She didn't know a single friend, and her heart felt lonely.", "“Will I be able to make friends here?”"],
        ["Watching from Afar", "At the playground, the other children were playing happily. Byeoli wanted to join them, but her feet wouldn't move.", "“Could I ask to play too?”"],
        ["Alone in the Shade", "Byeoli sat by herself under the shade of a tree. Deep inside, her heart kept wishing to play with them.", "She wished she had just a little more courage."],
        ["A Ball Rolls Over", "Just then, a ball rolled over and stopped right in front of Byeoli. The children called out, “Can you throw it back?”", "Byeoli's heart began to flutter."],
        ["One Brave Try", "Byeoli picked up the ball with both hands and threw it with all her might. It landed right where her new friends stood.", "“Thanks! Want to play with us?”"],
        ["The First Hello", "Byeoli gathered her courage, walked over, and said hello. “Hi, I'm Byeoli,” she said clearly.", "Once she reached out first, her heart felt lighter."],
        ["Playing Together", "Byeoli played ball with her new friends and had so much fun. Bright laughter spread all across the playground.", "“Playing together is a hundred times more fun!”"],
        ["Sharing Names", "The children called Byeoli by her name as they played along. Knowing each other's names made them feel even closer.", "“Byeoli, let's play again tomorrow!”"],
        ["See You Tomorrow", "As the sun went down, they waved goodbye to one another. Byeoli's lonely feeling had melted clean away.", "“I can't wait for tomorrow already!”"],
        ["The Courage to Reach Out", "Byeoli learned that when you reach out first, friends come your way. One small bit of courage had brought her brand-new friends.", "“I'm so glad I said hello first!”"]
      ]
    },
    "rainbow-plate-story.html": {
      title: "The Rainbow Plate",
      lead: "A story about Tongtong, a little pig who hated vegetables and learns the joy of eating every color.",
      pages: [
        ["I Don't Like Vegetables!", "Tongtong the little pig frowned at the sight of any green vegetable. He would push them off to the side of his plate.", "“I only want meat and bread!”"],
        ["Out of Energy", "Because he didn't eat a balanced meal, Tongtong ran out of energy fast. Even in the middle of playing, he grew tired quickly.", "“Why am I so worn out?”"],
        ["The Rainbow Plate", "Mama Pig set down a colorful rainbow plate for him. It was full of red tomatoes, orange carrots, and green broccoli.", "“Every color hides a different kind of power!”"],
        ["The Power of Red", "Tongtong gathered his courage and took a bite of red tomato. The sweet-and-tangy taste made his eyes go wide.", "“Oh! This is tastier than I thought!”"],
        ["The Power of Orange", "Next he munched on a crunchy orange carrot. Carrots, they said, make your eyes bright and sparkly.", "“Even the crunch is fun!”"],
        ["The Power of Green", "This time he picked up a piece of green broccoli. Green vegetables, they said, build a strong and healthy body.", "“Green isn't so bad after all!”"],
        ["A Clean Plate", "Before he knew it, Tongtong's rainbow plate was completely empty. He felt so proud that he had eaten every bit.", "“I ate it all, every last piece!”"],
        ["Bursting with Energy", "Eating every color filled his body with energy. Now Tongtong could run and play with his friends for ages.", "“I'm so full of energy now!”"],
        ["Showing His Friends", "Tongtong showed off his rainbow plate to all his friends. He happily told them each color holds a different power.", "“You should try eating a rainbow too!”"],
        ["Tongtong Eats a Rainbow", "Now Tongtong eats all sorts of colorful foods. He knows the rainbow plate is what keeps him strong.", "“Another rainbow plate, all gone today!”"]
      ]
    },
    "saying-sorry-story.html": {
      title: "Saying I'm Sorry",
      lead: "A story about Dudu, a puppy who upsets a friend and learns to say a heartfelt sorry.",
      pages: [
        ["The Castle Came Tumbling Down", "Dudu the puppy was running and kicked over his friend Squirrel's sandcastle. The carefully built castle came tumbling down.", "“Oops… I didn't mean to.”"],
        ["A Sad Squirrel", "Squirrel looked at the ruined castle with tears welling up. He had spent the whole morning making it.", "Squirrel's shoulders drooped low."],
        ["Pretending Not to Notice", "Feeling embarrassed, Dudu turned away and pretended not to notice. “It's just a sandcastle, anyway,” he mumbled.", "But one corner of his heart kept stinging."],
        ["A Friend Walks Away", "Squirrel walked off all by himself, feeling glum. Dudu watched his friend's back and felt heavy inside.", "“I think Squirrel was really upset.”"],
        ["Mama's Question", "Mama Dog gently asked Dudu how he was feeling. If you feel sorry, she said, you can share that feeling.", "“What should I do when I'm sorry?”"],
        ["Looking for His Friend", "Dudu gathered his courage and went to find Squirrel. His heart was pounding, but he really wanted to apologize.", "“Squirrel, can we talk for a minute?”"],
        ["From the Heart", "Dudu looked Squirrel in the eyes and spoke clearly. He said he was truly sorry for breaking the castle.", "“I'm sorry I knocked down your castle.”"],
        ["A Heart at Ease", "At the heartfelt apology, Squirrel's feelings gently softened. He nodded and said it was okay.", "“Thank you for being honest with me.”"],
        ["Building Again Together", "Dudu and Squirrel built an even grander castle together. With the two of them, it grew bigger and stronger.", "“It's even cooler now that we made it together!”"],
        ["The Power of Sorry", "Dudu learned that a heartfelt sorry can bring friends back together. One small apology mended a big friendship.", "“'Sorry'—just one word, and it's like magic!”"]
      ]
    },
    "shared-toy-story.html": {
      title: "The Toy We Both Want",
      lead: "A story about a bear and a rabbit who quarrel over one toy car and learn to make up.",
      pages: [
        ["The Red Car", "There was just one cool red car in the playroom. Bear and Rabbit grabbed it at the very same time.", "“I saw it first!” “No, I did!”"],
        ["A Tug of War", "The two pulled the car hard from either side. Their faces grew red and their hearts felt frustrated.", "“This one is mine!”"],
        ["Clunk, a Wheel Falls Off", "Just then, one of the car's wheels popped right off. Startled, they both let go at once.", "“Oh no… it's broken.”"],
        ["Turning Their Backs", "The two sat down with their backs to each other, all glum. After the fight, neither the car nor their hearts felt happy.", "Being angry wasn't any fun at all."],
        ["The Teacher's Words", "Teacher Cat came over and gently asked them a question. With only one toy, how could they both be happy?", "“Isn't there a way to share it?”"],
        ["A Good Idea", "Bear spoke up first: “How about we take turns?” Rabbit liked the idea and nodded.", "“If we take turns, we can both ride!”"],
        ["Fixing It Together", "Putting their heads together, they snapped the wheel back on. Fixing it together, the car was good as new in no time.", "“That was quick when we did it together!”"],
        ["Taking Turns", "Bear pushed the car first, and then it was Rabbit's turn. Taking turns, they had even more fun without any fighting.", "“Now it's your turn, here you go!”"],
        ["Sorry and Thank You", "The two told each other they were sorry, and thank you too. The knot in their hearts came gently undone.", "“I'm sorry about before.” “Me too.”"],
        ["More Fun Together", "Sharing turned out to be far more fun than fighting to keep it alone. Bear and Rabbit became the very best of friends.", "“Sharing makes it twice as fun!”"]
      ]
    },
    "sleepy-owl-story.html": {
      title: "The Owl Who Couldn't Sleep",
      lead: "A story about Bori, a baby owl who is afraid of the night and finds the cozy warmth in the dark.",
      pages: [
        ["A Night Without Sleep", "Baby owl Bori lay in the nest, just blinking his eyes. When the dark night came, his heart would start to race.", "“I can't fall asleep again tonight.”"],
        ["The Wobbling Shadow", "On the wall, a big shadow swayed back and forth. Bori hugged his blanket tight.", "“What is that? It's a little scary.”"],
        ["Mama's Little Lamp", "Mama Owl came over and lit a tiny starlight lamp. And then the shadow was just a swaying branch.", "“It's not something scary—it's the wind saying hello.”"],
        ["The Night Friends' Hello", "Outside the window, fireflies twinkled and glowed. There were so many friends awake and playing at night.", "Bori smiled a little and waved his wing."],
        ["The Moon's Lullaby", "The round moon wrapped Bori in its soft yellow light. The moonlight was gentle, like a warm blanket.", "“Sleep well, little owl.”"],
        ["The Wind's Blanket", "The night breeze rustled through the leaves as it passed by. To Bori, the sound was just like a lullaby.", "It wasn't a scary sound—it was a cozy one."],
        ["Counting the Stars", "Mama said, let's count the stars together: one, two, three. As he counted, his heart grew calmer and calmer.", "“One star, one little yawn.”"],
        ["At the Door to Dreamland", "Bori's eyelids slowly grew heavy. The dark didn't feel scary anymore—it felt cozy.", "“So night is a time for resting.”"],
        ["A Cozy Sleep", "Bori drifted off softly beside Mama's wing. The little lamp watched over him all night long.", "In his dreams, Bori flew above the stars."],
        ["A Brave Morning", "When the morning sun rose, Bori gave a great big stretch. Now he felt he could sleep on his own, even when night came.", "“I'll sleep well tonight too!”"]
      ]
    },
    "sun-moon-siblings-story.html": {
      title: "The Sun and Moon Siblings",
      lead: "An old folktale of a brother and sister who overcome danger with wisdom and courage and become the sun and the moon.",
      pages: [
        ["Waiting for Mother", "Long ago, a brother and his little sister lived in a thatched mountain cottage. They watched the house, waiting for their mother who had gone to sell rice cakes.", "“When will Mother come home?”"],
        ["A Knock at the Door", "When night fell, a voice outside called, “Mother is home.” But the voice was somehow rough and frightening.", "“That isn't our mother's voice.”"],
        ["The Strange Paw", "The children asked the voice to show its hand through the crack. The hand that came through was a tiger's paw, shaggy with fur.", "“That's not Mother—it's a tiger!”"],
        ["Up the Tree", "The siblings slipped out the back door and climbed up a tall tree. Calmly, they escaped the danger.", "“Quietly now—let's climb up high.”"],
        ["The Tiger Below", "The tiger looked up at the siblings from beneath the tree. It kept asking how they had climbed so high.", "The siblings held each other's hands tight."],
        ["A Prayer to the Sky", "The siblings prayed earnestly toward the sky. They folded their hands, hoping for help.", "“Heaven, please help us.”"],
        ["A Rope Comes Down", "Then a strong rope came sliding down from the sky. The siblings held on tight and rose up toward the heavens.", "“Hold on tight—let's go up together!”"],
        ["Rising to the Sky", "Holding the rope, the siblings climbed higher and higher into the sky. They were able to get far away from the scary tiger.", "“We're safe now—what a relief!”"],
        ["Becoming Sun and Moon", "Up in the sky, the brother became the sun, and the sister became the moon. Together they watched over each other and lit up the sky.", "“I'll shine on the day, and you shine on the night.”"],
        ["Lighting Day and Night", "And so the sun lights the day and the moon lights the night. A calm heart and love for each other had kept the siblings safe.", "“We are always together in the sky.”"]
      ]
    },
    "tearful-rain-story.html": {
      title: "The Day It Rained Tears",
      lead: "A story about Dani, a little fox who loses a beloved balloon and learns the comfort of being cared for.",
      pages: [
        ["The Red Balloon Floats Away", "Dani the little fox's beloved red balloon slipped right out of his hand. It floated up, up, high into the sky.", "“My balloon… don't go!”"],
        ["Tears Welling Up", "Big tears welled up in Dani's eyes. He felt so sad, as if his chest were empty inside.", "The tears came pattering down."],
        ["It's Okay to Cry", "Mama Fox came over and held Dani gently. It's okay to cry, she said—feeling sad is only natural.", "“You can cry as much as you need, Dani.”"],
        ["Sharing His Heart", "Dani told his mama how much he had loved that balloon. Once he put his sadness into words, his chest felt a little lighter.", "“I loved it so much, that's why it hurt more.”"],
        ["The Tears Stop", "After crying for a while, his tears slowly began to dry. Dani wiped them away with the back of his hand.", "The rain in his heart slowly stopped."],
        ["The Balloon's Journey", "Mama told him the balloon had gone off on a faraway journey. Maybe it was playing with its cloud friends, she said.", "“So my balloon went off on an adventure.”"],
        ["A Friend's Comfort", "Rabbit, passing by, patted Dani gently on the shoulder. When you're sad, a friend by your side is a great comfort.", "“I'll stay right here with you.”"],
        ["A Brand-New Game", "Together they folded paper airplanes and sent them flying. Where the sadness had been, a new kind of fun arrived.", "“This time I'll hold onto my airplane tight!”"],
        ["Sunlight in His Heart", "Warm sunlight broke through between the clouds. A bright light came back into Dani's heart too.", "After the sadness came the sunshine."],
        ["A Heart Made Better", "Dani learned that even sad days come to an end. Thanks to the people beside him, his heart grew warm again.", "“It's okay to be sad. I can smile again.”"]
      ]
    },
    "three-coins-story.html": {
      title: "The Three Coins",
      lead: "A story about Dori, a baby raccoon who gets his first allowance and learns to spend, save, and share.",
      pages: [
        ["Three Shiny Coins", "Dori the baby raccoon got his very first allowance: three coins. They sparkled brightly in his little hand.", "“Wow, I have my own coins!”"],
        ["The Candy He Wanted", "The shop window was full of colorful candy. Dori wanted to spend all his coins on it.", "“Should I buy candy with all of them?”"],
        ["Three Jars", "Mama raccoon showed him three jars. One was for spending, one for saving, and one for sharing.", "“What if you split your coins up?”"],
        ["One for Spending", "Dori dropped his first coin into the spending jar. Today he would buy just one little candy.", "“I'll pick only one.”"],
        ["One for Saving", "His second coin went into the saving jar. If he saved bit by bit, he could buy something bigger.", "“If I save, I can buy a wonderful picture book!”"],
        ["One for Sharing", "The third coin went into the sharing jar. That coin was for a friend who needed help.", "“Sharing makes your heart feel warm.”"],
        ["One Sweet Candy", "Dori bought one candy with the coin from his spending jar. Even just one made him happy enough.", "“Even one tastes so good!”"],
        ["The Heavier Jar", "After a few days, the saving jar grew heavy. Dori shook it and smiled proudly.", "“Saving little by little adds up so much!”"],
        ["The Joy of Sharing", "Dori gave the coin from his sharing jar to a friend in need. His friend's bright smile made Dori happy too.", "“Sharing makes my heart feel rich!”"],
        ["A Smart Coin Owner", "Dori learned how to spend, save, and share. He found that even small coins, used wisely, become big happiness.", "“Now I'm a raccoon who knows how to use coins!”"]
      ]
    },
    "thunder-night-story.html": {
      title: "The Scary Thunder Night",
      lead: "A story about Somi, a baby rabbit who is afraid of thunder and learns to face her fear.",
      pages: [
        ["Boom! Crash!", "Thunder boomed and crashed across the night sky. Somi the baby rabbit jumped and hid under her blanket.", "“Thunder is so scary!”"],
        ["The Flashing Sky", "Outside the window, lightning flashed again and again. Raindrops tapped softly on the glass.", "Somi covered her ears tight."],
        ["Daddy Came", "Daddy rabbit lifted the blanket and hugged Somi close. In his warm arms, her shaking slowly stopped.", "“It's okay, Daddy is right here.”"],
        ["The Secret of Thunder", "Daddy told her that thunder is the sound of clouds clapping. It's loud, but it can't hurt us.", "“The clouds are clapping because they're happy.”"],
        ["Between Lightning and Thunder", "Daddy said they should count one, two, three after each flash. While they counted, the thunder rolled farther away.", "“Counting makes it less scary!”"],
        ["A Warm Cup", "Mommy brought a warm cup of cocoa. As her hands grew warm, her heart grew soft and cozy.", "There was a special coziness on a rainy night."],
        ["Watching the Rain", "Somi watched the rain with her family by the window. The water was soaking the dry ground.", "“The flowers must be happy that it's raining.”"],
        ["The Thunder Fades", "The thunder grew quieter and faded far away. Before she knew it, Somi gave a big yawn.", "Her scared feeling melted away."],
        ["Peaceful Sleep", "Somi fell fast asleep beside her family. The sound of rain became a gentle lullaby.", "Now thunder didn't scare her at all."],
        ["A Clear Morning", "When morning came, a big rainbow filled the sky. Somi learned that a pretty gift comes after a scary night.", "“After a scary night, a rainbow comes!”"]
      ]
    },
    "tidy-wizard-story.html": {
      title: "The Little Tidy-Up Wizard",
      lead: "A story about Nana, a baby cat who cleans her messy room and learns the magic of tidying up.",
      pages: [
        ["The Messy Room", "Nana the baby cat's room was so full of toys she could barely step anywhere. Blocks and dolls were scattered everywhere.", "“Huh, where did my car go?”"],
        ["Ouch, That Hurts!", "Nana stepped on a block on the floor and hopped in pain. A messy room was no fun to play in.", "“I can't find anything I'm looking for.”"],
        ["The Magic Box", "Mama cat handed her a colorful tidy-up box. She said magic happens when every thing gets its own place.", "“This is a magic tidy-up box.”"],
        ["Blocks in the Blue Box", "Nana gathered the blocks and dropped them into the blue box. Sorting like with like made tidying quick.", "“Blocks, this is your home!”"],
        ["Dolls on the Shelf", "She sat the dolls in a row up on the shelf. With the dolls lined up, the room looked brighter.", "“Rest here comfortably, dolls!”"],
        ["Books on the Bookshelf", "She tucked the scattered picture books neatly onto the bookshelf. The lined-up spines looked so nice.", "“Now I can find the book I want right away!”"],
        ["A Sparkling Room", "Before long, the room was sparkling clean. Nana spun around and around in the open space.", "“The magic really happened!”"],
        ["Found It, My Car!", "While tidying, her lost car popped right up. When things have a place, they don't disappear.", "“There you are, nice to see you!”"],
        ["A Friend Comes Over", "A friend came to play in the clean room. On the wide floor, the two could run around to their hearts' content.", "“A big room is even more fun!”"],
        ["The Little Tidy-Up Wizard", "Nana learned that giving each thing a place makes a room magically clean. Now she tidies up by herself after playing.", "“Done playing? Back in place, tidy-up magic!”"]
      ]
    },
    "tiger-gotgam-story.html": {
      title: "The Tiger and the Dried Persimmon",
      lead: "An old Korean tale about a tiger who gets a fright from a single word that calms a crying baby: gotgam, the dried persimmon.",
      pages: [
        ["The Tiger in the Deep Mountains", "Long, long ago, a big tiger lived deep in the mountains. Hungry, he crept down toward the village.", "“What shall I eat tonight?”"],
        ["A Baby's Cry", "From a thatched cottage came the sound of a crying baby. The tiger perked up his ears by the window.", "“Waah, waah!”"],
        ["The Tiger Is Here!", "The mother said, “A tiger is here!” to soothe the baby, but the baby kept crying. Hearing his own name, the tiger gave a proud shrug.", "“Hmm, everyone is afraid of me.”"],
        ["I'll Give You a Gotgam", "When the mother said, “I'll give you a gotgam,” the baby stopped crying at once. The room suddenly went quiet.", "“Huh? The crying stopped in an instant?”"],
        ["Who Is Gotgam?", "The tiger thought a gotgam must be something scarier than himself. The baby cried at his name but hushed for a gotgam!", "“A gotgam must be stronger than me!”"],
        ["A Cow Thief Arrives", "Just then, a thief who came to steal a cow mistook the tiger in the dark for a cow. He quietly climbed onto the tiger's back.", "“There we go, I'll lead this cow away.”"],
        ["The Gotgam Climbed On!", "The tiger thought the thing on his back was the scary gotgam. He trembled all over in fright.", "“Yikes, the gotgam is on my back!”"],
        ["Run for My Life!", "The tiger raced toward the mountains to shake off the gotgam. The startled thief slipped and tumbled off.", "“Run, run for my life!”"],
        ["The Talk of the Village", "The next day, the whole village buzzed with the tiger's story. They all laughed about a tiger afraid of a gotgam.", "“The scary tiger ran away from a dried persimmon!”"],
        ["A Sweet Gotgam Night", "The baby fell fast asleep holding a sweet gotgam. It's an old tale about how we fear things for no reason when we don't understand them.", "“A gotgam was really just a sweet treat.”"]
      ]
    },
    "water-village-story.html": {
      title: "The Village That Saved Water",
      lead: "A story about a toad village that learns to save water to bring its dried-up spring back to life.",
      pages: [
        ["The Trickling Village Spring", "In the middle of the toad village, a clear spring trickled along. The friends drank and washed with its water.", "“Our spring is always so clear!”"],
        ["Water Running Wild", "But the friends left the water running and let it pour away. Even when they weren't using it, the water gushed on.", "“There's endless water, so why worry?”"],
        ["The Dried-Up Spring", "One summer day, the spring dried up and showed its bare bottom. The friends were shocked and stamped their feet.", "“Not even one drop is coming out!”"],
        ["Grandma's Story", "Wise Grandma toad gathered the friends together. Water is precious, she said, and if they used it carefully, it would fill up again.", "“Let's save every single drop.”"],
        ["Caught in a Cup", "The friends caught water in a cup when they brushed their teeth. With the tap off, they used far less water.", "“Just doing this saves so much!”"],
        ["Water Used Again", "They didn't throw away the water from washing vegetables; they gave it to the garden. Even used water could work again.", "“Water can do two jobs!”"],
        ["Collecting Rainwater", "On rainy days, they collected rainwater in big jars. They cleaned with it and gave it to the flowers.", "“Even water from the sky, used wisely!”"],
        ["The Water Returns", "As everyone saved, water slowly began to gather in the dry spring. Tiny drops bubbled up, plip-plop.", "“Look! The spring is coming back to life!”"],
        ["The Spring Revived", "A few days later, the spring trickled clear once more. The friends held hands and hopped with joy.", "“Together, we saved our spring!”"],
        ["Water Is Precious", "The village friends learned that even one drop of water is precious. Now everyone saves water and keeps the spring clear.", "“If we all save every drop, everyone is happy!”"]
      ]
    },
    "we-are-different-story.html": {
      title: "I Love That We're Different",
      lead: "A story about animal friends, each one different, who discover the joy of being unique.",
      pages: [
        ["All Different Friends", "In the forest village lived a tall giraffe and a tiny hedgehog. Everyone looked completely different.", "“Why are we all so different?”"],
        ["The Giraffe's Long Neck", "The giraffe easily picked the fruit on the high branches. Thanks to his long neck, he reached fruit no one else could.", "“My long neck is really helpful!”"],
        ["The Hedgehog's Spines", "The hedgehog poked the fallen chestnuts onto her spines and carried them off. Even pointy spines were a wonderful talent.", "“Small as I am, there's something only I can do.”"],
        ["The Mole's Underground Path", "The mole dug a cool tunnel underground. It was a secret passage where friends could rest on hot days.", "“My eyes are small, but I know underground best.”"],
        ["The Bird's Wings", "The little bird spread her wings and carried news far away. She quickly brought back word from friends across the river.", "“I can fly, so I can go far.”"],
        ["The Turtle's Sturdy Shell", "The turtle carried his friends across the river on his sturdy back. Slow as he was, he made the safest boat.", "“Slow as we went, everyone arrived safely.”"],
        ["Talents Together", "The friends put their talents together and built a wonderful tree house. What no one could do alone, they did together.", "“Put our differences together and it's even better!”"],
        ["Each Other's Good Points", "The friends began to praise one another's differences. They learned it's more fun because they aren't all the same.", "“I really love that you're different from me.”"],
        ["A Dance Together", "Everyone gathered in a circle and danced their own dance. Big moves and small moves were all beautiful.", "Different, but one group, we are friends!"],
        ["Difference Is a Gift", "Now the friends aren't shy about being different. They know that being different is the most wonderful gift.", "“Because we're all different, the world is brighter.”"]
      ]
    },
  };

  const pageName = location.pathname.split("/").pop();
  const englishStory = ENGLISH_STORIES[pageName] || null;
  const hasEnglish = !!englishStory;

  const titleNode = document.querySelector(".hero h1");
  const leadNode = document.querySelector(".hero .lead");
  const spreads = Array.from(document.querySelectorAll(".story-spread"));
  if (!spreads.length) return;
  const pageGrid = document.querySelector(".page-grid");
  let currentLang = "ko";
  let currentPage = 0;
  const readButtons = [];
  const stopButtons = [];
  let prevButton;
  let nextButton;
  let transitionTimer;
  let readingToken = 0;
  let readingActive = false;

  const koreanStory = {
    title: titleNode ? titleNode.textContent : "",
    lead: leadNode ? leadNode.textContent : "",
    pages: spreads.map((spread) => {
      const heading = spread.querySelector(".scene-copy h2");
      const paras = spread.querySelectorAll(".scene-copy p:not(.line)");
      const line = spread.querySelector(".scene-copy .line");
      return [
        heading ? heading.textContent : "",
        paras[0] ? paras[0].textContent : "",
        line ? line.textContent : "",
        paras[1] ? paras[1].textContent : ""
      ];
    })
  };

  function storyFor(lang) {
    return lang === "en" ? englishStory : koreanStory;
  }

  function applyLanguage(lang) {
    const story = storyFor(lang);
    currentLang = lang;
    document.documentElement.lang = lang === "en" ? "en" : "ko";
    document.title = (lang === "en" ? "Picture Story - " : "그림동화 - ") + story.title;
    if (titleNode) titleNode.textContent = story.title;
    if (leadNode) leadNode.textContent = story.lead;
    if (pageGrid) pageGrid.setAttribute("aria-label", lang === "en" ? "Picture story text" : "그림동화 본문");

    spreads.forEach((spread, index) => {
      const page = story.pages[index];
      if (!page) return;
      const heading = spread.querySelector(".scene-copy h2");
      const paras = spread.querySelectorAll(".scene-copy p:not(.line)");
      const line = spread.querySelector(".scene-copy .line");
      if (heading) heading.textContent = page[0];
      if (paras[0]) paras[0].textContent = page[1];
      if (line) line.textContent = page[2];
      if (paras[1] && page[3] != null && page[3] !== "") paras[1].textContent = page[3];
    });

    document.querySelectorAll("[data-story-lang]").forEach((button) => {
      const active = button.dataset.storyLang === lang;
      button.classList.toggle("active", active);
      button.setAttribute("aria-pressed", active ? "true" : "false");
    });

    readButtons.forEach((button) => { button.textContent = lang === "en" ? "Read Story" : "읽기"; });
    stopButtons.forEach((button) => { button.textContent = lang === "en" ? "Stop" : "정지"; });
    stopReading();
  }

  function updateCarousel(previousPage = currentPage) {
    if (!spreads.length) return;
    const pageChanged = previousPage !== currentPage;
    const direction = pageChanged && previousPage < currentPage ? "next" : "prev";

    clearTimeout(transitionTimer);

    spreads.forEach((spread, index) => {
      const active = index === currentPage;
      const leaving = pageChanged && index === previousPage;
      spread.classList.remove("is-active", "is-exiting", "from-next", "from-prev", "to-next", "to-prev");

      if (active || leaving) {
        spread.hidden = false;
      } else {
        spread.hidden = true;
      }

      spread.classList.toggle("is-active", active);
      spread.classList.toggle("is-exiting", leaving);
      if (active && pageChanged) spread.classList.add(direction === "next" ? "from-next" : "from-prev");
      if (leaving) spread.classList.add(direction === "next" ? "to-next" : "to-prev");
      spread.setAttribute("aria-hidden", active ? "false" : "true");
    });

    if (prevButton && nextButton) {
      prevButton.disabled = currentPage === 0;
      prevButton.classList.toggle("is-hidden", prevButton.disabled);
      nextButton.disabled = currentPage === spreads.length - 1;
      nextButton.classList.toggle("is-hidden", nextButton.disabled);
      // 화살표를 활성 장면의 삽화 위로 옮긴다 (영어 단어 카드와 같은 오버레이 방식)
      const host = spreads[currentPage].querySelector(".scene-art") || spreads[currentPage];
      host.appendChild(prevButton);
      host.appendChild(nextButton);
    }

    if (pageChanged) {
      transitionTimer = setTimeout(() => {
        spreads.forEach((spread, index) => {
          const active = index === currentPage;
          spread.hidden = !active;
          spread.classList.toggle("is-active", active);
          spread.classList.remove("is-exiting", "from-next", "from-prev", "to-next", "to-prev");
          spread.setAttribute("aria-hidden", active ? "false" : "true");
        });
      }, 420);
    }
  }

  // 인접 장면의 lazy 삽화를 미리 로드해 장 넘김 시 빈 화면을 줄인다.
  function preloadNeighborArt(pageIndex) {
    [pageIndex + 1, pageIndex - 1].forEach((idx) => {
      const spread = spreads[idx];
      if (!spread) return;
      const img = spread.querySelector(".image-scene img");
      if (img && img.loading === "lazy") img.loading = "eager";
    });
  }

  function showPage(pageIndex, options = {}) {
    if (!spreads.length) return;
    const nextPage = Math.max(0, Math.min(pageIndex, spreads.length - 1));
    if (nextPage === currentPage) return;
    const previousPage = currentPage;
    currentPage = nextPage;
    updateCarousel(previousPage);
    preloadNeighborArt(nextPage);
    if (readingActive && !options.fromReading) stopReading();
  }

  function createCarousel() {
    if (!pageGrid || spreads.length < 2) return;

    pageGrid.classList.add("story-carousel");
    pageGrid.setAttribute("aria-live", "polite");

    prevButton = document.createElement("button");
    prevButton.type = "button";
    prevButton.className = "story-art-btn story-prev-btn";
    prevButton.setAttribute("aria-label", "이전 페이지");
    prevButton.textContent = "‹";

    nextButton = document.createElement("button");
    nextButton.type = "button";
    nextButton.className = "story-art-btn story-next-btn";
    nextButton.setAttribute("aria-label", "다음 페이지");
    nextButton.textContent = "›";

    prevButton.addEventListener("click", () => showPage(currentPage - 1));
    nextButton.addEventListener("click", () => showPage(currentPage + 1));

    let touchStartX = 0;
    pageGrid.addEventListener("touchstart", (event) => {
      touchStartX = event.changedTouches[0].clientX;
    }, { passive: true });
    pageGrid.addEventListener("touchend", (event) => {
      const deltaX = event.changedTouches[0].clientX - touchStartX;
      if (Math.abs(deltaX) < 48) return;
      showPage(currentPage + (deltaX < 0 ? 1 : -1));
    }, { passive: true });

    document.addEventListener("keydown", (event) => {
      if (event.key === "ArrowLeft") showPage(currentPage - 1);
      if (event.key === "ArrowRight") showPage(currentPage + 1);
    });

    updateCarousel();
    preloadNeighborArt(currentPage);
  }

  function scrollToFirstCard() {
    if (!pageGrid || location.hash) return;
    requestAnimationFrame(() => {
      pageGrid.scrollIntoView({ block: "start" });
    });
  }

  function textForPage(pageIndex) {
    const story = storyFor(currentLang);
    const page = story.pages[pageIndex];
    if (!page) return "";
    const parts = pageIndex === 0 ? [story.title, story.lead] : [];
    parts.push(page[0], page[1], page[3] || "", page[2]);
    return parts.filter(Boolean).join(". ");
  }

  function setReadingState(isReading) {
    readingActive = isReading;
    readButtons.forEach((button) => {
      button.classList.toggle("is-reading", isReading);
      button.textContent = isReading
        ? (currentLang === "en" ? "Reading..." : "읽는 중")
        : (currentLang === "en" ? "Read Story" : "읽기");
    });
    stopButtons.forEach((button) => { button.disabled = !isReading; });
  }

  function stopReading() {
    readingToken += 1;
    if ("speechSynthesis" in window) window.speechSynthesis.cancel();
    setReadingState(false);
  }

  function speakPage(pageIndex, token) {
    if (!("speechSynthesis" in window) || token !== readingToken) return;
    const story = storyFor(currentLang);
    if (!story.pages[pageIndex]) {
      setReadingState(false);
      return;
    }

    showPage(pageIndex, { fromReading: true });

    const utterance = new SpeechSynthesisUtterance(textForPage(pageIndex));
    utterance.lang = currentLang === "en" ? "en-US" : "ko-KR";
    const v = CourseCommon.pickVoiceFor(utterance.lang);
    if (v) utterance.voice = v;
    utterance.rate = currentLang === "en" ? 0.9 : 0.95;
    utterance.pitch = 1.05;
    utterance.onend = () => {
      if (token !== readingToken) return;
      if (pageIndex < story.pages.length - 1) {
        window.setTimeout(() => speakPage(pageIndex + 1, token), 320);
      } else {
        setReadingState(false);
      }
    };
    utterance.onerror = () => {
      if (token === readingToken) setReadingState(false);
    };
    window.speechSynthesis.speak(utterance);
  }

  function readStory() {
    if (!("speechSynthesis" in window)) return;
    readingToken += 1;
    const token = readingToken;
    window.speechSynthesis.cancel();
    setReadingState(true);
    speakPage(currentPage, token);
  }

  function buildToolbar() {
    const toolbar = document.createElement("div");
    toolbar.className = "story-toolbar";
    toolbar.setAttribute("aria-label", "동화 언어와 읽기");
    toolbar.innerHTML =
      (hasEnglish
        ? '<div class="story-lang-toggle" role="group" aria-label="언어 선택">' +
            '<button type="button" data-story-lang="ko" class="active" aria-pressed="true">한국어</button>' +
            '<button type="button" data-story-lang="en" aria-pressed="false">English</button>' +
          '</div>'
        : '') +
      '<div class="story-read-actions">' +
        '<button type="button" class="story-read-btn">읽기</button>' +
        '<button type="button" class="story-stop-btn" disabled>정지</button>' +
      '</div>';

    const readBtn = toolbar.querySelector(".story-read-btn");
    const stopBtn = toolbar.querySelector(".story-stop-btn");
    toolbar.querySelectorAll("[data-story-lang]").forEach((button) => {
      button.addEventListener("click", () => applyLanguage(button.dataset.storyLang));
    });
    readBtn.addEventListener("click", readStory);
    stopBtn.addEventListener("click", stopReading);
    if (!("speechSynthesis" in window)) {
      readBtn.disabled = true;
      stopBtn.disabled = true;
    }
    readButtons.push(readBtn);
    stopButtons.push(stopBtn);
    return toolbar;
  }

  function createToolbar() {
    const heroCopy = document.querySelector(".hero-copy");
    if (heroCopy) heroCopy.appendChild(buildToolbar());
    // 본문 아래에도 같은 툴바를 한 번 더 — 끝까지 읽고 나서 바로 조작할 수 있게
    if (pageGrid) {
      const bottomToolbar = buildToolbar();
      bottomToolbar.classList.add("story-toolbar-bottom");
      pageGrid.after(bottomToolbar);
    }
  }

  window.addEventListener("pagehide", stopReading);
  createToolbar();
  createCarousel();
  scrollToFirstCard();
})();
